-- 52 Model Railway: the ferry. Its `path_follow` goes `once`; at each
-- end the engine calls on_path_end, and this waits at the jetty and sets off
-- back the other way. Generated by tools/gen_scenes.py.

local wait, speed = 0, 26

function on_path_end(entity)
    wait = 2.0
end

function update(entity, dt)
    if wait > 0 then
        wait = wait - dt
        if wait <= 0 then
            speed = -speed
            PathFollow.set(entity, "speed", speed)
            PathFollow.set(entity, "playing", true)
        end
    end
end
